<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/admin/finance/products<?= $editing?'/'.(int)$product['id']:'' ?>"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label for="product-name">Curso <span class="required">*</span></label><input id="product-name" name="name" maxlength="160" value="<?= $escape($product['name']??'') ?>" required></div><div class="form-field"><label for="product-unit">Disponibilidade</label><select id="product-unit" name="unit_id"><option value="">Todas as unidades</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"<?= isset($product['unit_id'])&&(int)$product['unit_id']===(int)$unit['id']?' selected':'' ?>><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="product-value">Preço <span class="required">*</span></label><input id="product-value" name="value" type="number" min="5" step="0.01" value="<?= $editing?$escape(number_format((float)$product['value'],2,'.','')):'' ?>" required></div><div class="form-field"><label for="product-expiration">Validade do link <span class="required">*</span></label><select id="product-expiration" name="minutes_to_expire" required><?php foreach([30=>'30 minutos',60=>'1 hora',360=>'6 horas',720=>'12 horas',1440=>'24 horas']as$value=>$label):?><option value="<?= $value ?>"<?= (int)($product['minutes_to_expire']??1440)===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></div><div class="form-field form-field-full"><label for="product-description">Descrição</label><textarea id="product-description" name="description" maxlength="500" rows="3"><?= $escape($product['description']??'') ?></textarea></div></div><fieldset><legend>Formas aceitas <span class="required">*</span></legend><div class="checks"><label><input type="checkbox" name="billing_types[]" value="PIX"<?= in_array('PIX',$selected,true)?' checked':'' ?>> Pix</label><label><input type="checkbox" name="billing_types[]" value="CREDIT_CARD"<?= in_array('CREDIT_CARD',$selected,true)?' checked':'' ?>> Cartão de crédito</label></div></fieldset><label class="check-option"><input type="checkbox" name="is_active" value="1"<?= !$editing||(int)$product['is_active']===1?' checked':'' ?>> Curso ativo e disponível para checkout</label><div class="form-actions"><button class="button-primary" type="submit">Salvar curso e preço</button></div></form></div></section>
